<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Product; use App\Services\CartService; use Illuminate\Http\Request;
class CartController extends Controller { public function __construct(private CartService $carts){} private function cart(Request $r){return $this->carts->current($r->user()?->id, $r->hasSession() ? $r->session()->getId() : null);} public function show(Request $r){$cart=$this->cart($r)->load('items.product.images','coupon');return response()->json(['data'=>$cart,'totals'=>$this->carts->totals($cart)]);} public function store(Request $r){$d=$r->validate(['product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1|max:50']);return response()->json(['data'=>$this->carts->add($this->cart($r),Product::findOrFail($d['product_id']),$d['quantity'])],201);} public function update(Request $r,int $item){$d=$r->validate(['quantity'=>'required|integer|min:1|max:50']);$cart=$this->cart($r);$cart->items()->whereKey($item)->firstOrFail()->update($d);return response()->json(['data'=>$cart->fresh('items.product'),'totals'=>$this->carts->totals($cart->fresh('items'))]);} public function destroy(Request $r,int $item){$this->cart($r)->items()->whereKey($item)->delete();return response()->noContent();} }
